ddl:
CREATE TABLE Document_Type (
    Document_Type_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255),
    Version_Number VARCHAR(255)
);

CREATE TABLE Status_Category (
    Name VARCHAR(255),
    Status_Category_ID INTEGER PRIMARY KEY,
    Version_Number VARCHAR(255)
);

CREATE TABLE Status (
    Name VARCHAR(255),
    Sequence_Number VARCHAR(255),
    Status_ID INTEGER PRIMARY KEY
);

CREATE TABLE Status_Category_Document_Type (
    Document_Type_ID INTEGER NOT NULL,
    Status_Category_ID INTEGER NOT NULL,
    PRIMARY KEY (Status_Category_ID, Document_Type_ID),
    FOREIGN KEY (Document_Type_ID) REFERENCES Document_Type(Document_Type_ID),
    FOREIGN KEY (Status_Category_ID) REFERENCES Status_Category(Status_Category_ID)
);

CREATE TABLE Status_Status_Category (
    Status_Category_ID INTEGER NOT NULL,
    Status_ID INTEGER NOT NULL,
    PRIMARY KEY (Status_ID, Status_Category_ID),
    FOREIGN KEY (Status_Category_ID) REFERENCES Status_Category(Status_Category_ID),
    FOREIGN KEY (Status_ID) REFERENCES Status(Status_ID)
);
